package com.gen3d.remote.tests;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import android.webkit.*;import java.util.concurrent.atomic.*;
public class RecoveryTest extends Instrumentation{public void onCreate(Bundle b){super.onCreate(b);start();}View find(View v,String text){if(v instanceof Button&&((Button)v).getText().toString().equalsIgnoreCase(text))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View f=find(g.getChildAt(i),text);if(f!=null)return f;}}return null;}WebView findWeb(View v){if(v instanceof WebView)return (WebView)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){WebView found=findWeb(g.getChildAt(i));if(found!=null)return found;}}return null;}public void onStart(){Bundle b=new Bundle();try{Activity a=startActivitySync(new Intent().setClassName("com.gen3d.remote","com.gen3d.remote.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));if(Build.VERSION.SDK_INT<29)throw new Exception("Recovery test requires Android API 29 or later.");runOnMainSync(()->{WebView w=findWeb(a.getWindow().getDecorView());if(w!=null&&w.getWebViewRenderProcess()!=null)w.getWebViewRenderProcess().terminate();});AtomicBoolean ready=new AtomicBoolean();for(int i=0;i<140&&!ready.get();i++){runOnMainSync(()->{View v=a.getWindow().getDecorView();View reload=find(v,"Reload remote view");ready.set(reload!=null&&reload.getVisibility()==View.VISIBLE&&!find(v,"Open desktop remote").isEnabled()&&!find(v,"Offline library & KJV Bible").isEnabled());});Thread.sleep(500);}if(!ready.get())throw new Exception("Renderer crash did not show safe recovery controls");ActivityMonitor monitor=addMonitor("com.gen3d.remote.MainActivity",null,false);runOnMainSync(()->find(a.getWindow().getDecorView(),"Reload remote view").performClick());Activity next=waitForMonitorWithTimeout(monitor,30000);if(next==null||next==a)throw new Exception("Reload did not recreate the activity");b.putString("gen3d_recovery","PASS");b.putString("checks","renderer termination handled, host activity survived, unsafe controls disabled, native Reload recreated remote view");finish(Activity.RESULT_OK,b);}catch(Throwable e){b.putString("gen3d_recovery","FAIL");b.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,b);}}}
